-- Run with psql -v ON_ERROR_STOP=1 -f test/sql/batch_equiv.sql against the challenge schema.
-- The database is read-only. Each round samples existing data plus missing values.
DO $test$
DECLARE
    slugs text[]; tag_names text[]; user_names text[];
    viewers bigint[]; limits int[]; offsets int[];
    available_slugs text[]; available_tags text[]; available_users text[]; available_viewers bigint[];
    old_sql text; new_sql text; differs boolean; round_no int;
BEGIN
    SELECT array_agg(slug) INTO available_slugs FROM (SELECT slug FROM articles ORDER BY id DESC LIMIT 100) s;
    SELECT array_agg(name) INTO available_tags FROM (SELECT name FROM tags ORDER BY id LIMIT 100) s;
    SELECT array_agg(username), array_agg(id) INTO available_users, available_viewers FROM (SELECT username,id FROM users ORDER BY id LIMIT 100) s;
    available_slugs := COALESCE(available_slugs, ARRAY[]::text[]);
    available_tags := COALESCE(available_tags, ARRAY[]::text[]);
    available_users := COALESCE(available_users, ARRAY[]::text[]);
    available_viewers := COALESCE(available_viewers, ARRAY[]::bigint[]);
    FOR round_no IN 1..5 LOOP
        SELECT array_agg(CASE WHEN i % 7 = 0 OR cardinality(available_slugs) = 0 THEN '__batch_equiv_missing_slug__' ELSE available_slugs[1 + (CASE WHEN i % 3 = 0 THEN 0 ELSE floor(random() * cardinality(available_slugs))::int END)] END ORDER BY i),
               array_agg(CASE WHEN i % 7 = 0 OR cardinality(available_tags) = 0 THEN '__batch_equiv_missing_tag__' ELSE available_tags[1 + (CASE WHEN i % 3 = 0 THEN 0 ELSE floor(random() * cardinality(available_tags))::int END)] END ORDER BY i),
               array_agg(CASE WHEN i % 7 = 0 OR cardinality(available_users) = 0 THEN '__batch_equiv_missing_user__' ELSE available_users[1 + (CASE WHEN i % 3 = 0 THEN 0 ELSE floor(random() * cardinality(available_users))::int END)] END ORDER BY i),
               array_agg(CASE WHEN i % 2 = 0 OR cardinality(available_viewers) = 0 THEN 0::bigint ELSE available_viewers[1 + floor(random() * cardinality(available_viewers))::int] END ORDER BY i),
               array_agg(CASE WHEN i % 5 = 0 THEN 1 WHEN i % 11 = 0 THEN 100 ELSE 10 END ORDER BY i),
               array_agg(CASE WHEN i % 2 = 0 THEN 0 WHEN i % 7 = 0 THEN 10000 ELSE floor(random() * 40)::int END ORDER BY i)
        INTO slugs, tag_names, user_names, viewers, limits, offsets FROM generate_series(1,40) i;
        -- ARTICLE_BATCH: original SQL followed by the rewritten SQL from Stmt.java.
        old_sql := $old$SELECT r.i::int4,q.* FROM unnest($1::text[],$2::int8[]) WITH ORDINALITY AS r(slug,viewer,i) CROSS JOIN LATERAL (SELECT a.id,a.slug,a.title,a.description,a.body,a.created_at,a.updated_at,ARRAY(SELECT t.name FROM article_tags at JOIN tags t ON t.id=at.tag_id WHERE at.article_id=a.id ORDER BY t.name),(SELECT count(*) FROM favorites f WHERE f.article_id=a.id),EXISTS(SELECT 1 FROM favorites f WHERE f.user_id=r.viewer AND f.article_id=a.id),u.username,u.bio,u.image,EXISTS(SELECT 1 FROM follows fo WHERE fo.follower_id=r.viewer AND fo.followee_id=a.author_id) FROM articles a JOIN users u ON u.id=a.author_id WHERE a.slug=r.slug) q$old$;
        new_sql := $new$WITH r AS MATERIALIZED (SELECT * FROM unnest($1::text[],$2::int8[]) WITH ORDINALITY AS r(slug,viewer,i)), m AS MATERIALIZED (SELECT r.i,r.viewer,a.id,a.slug,a.title,a.description,a.body,a.created_at,a.updated_at,a.author_id FROM r JOIN articles a ON a.slug=r.slug), ids AS (SELECT DISTINCT id,author_id FROM m), deco AS MATERIALIZED (SELECT ids.id,tg.tags,(SELECT count(*) FROM favorites f WHERE f.article_id=ids.id) AS fav_count,u.username,u.bio,u.image FROM ids JOIN users u ON u.id=ids.author_id LEFT JOIN (SELECT at.article_id,array_agg(t.name ORDER BY t.name) AS tags FROM ids ti JOIN article_tags at ON at.article_id=ti.id JOIN tags t ON t.id=at.tag_id GROUP BY at.article_id) tg ON tg.article_id=ids.id) SELECT r.i::int4,r.id,r.slug,r.title,r.description,r.body,r.created_at,r.updated_at,COALESCE(d.tags,ARRAY[]::text[]) AS array,COALESCE(d.fav_count,0::bigint) AS count,EXISTS(SELECT 1 FROM favorites f WHERE f.user_id=r.viewer AND f.article_id=r.id),d.username,d.bio,d.image,EXISTS(SELECT 1 FROM follows fo WHERE fo.follower_id=r.viewer AND fo.followee_id=r.author_id) FROM m r JOIN deco d ON d.id=r.id ORDER BY r.i$new$;
        EXECUTE 'WITH old_rows AS MATERIALIZED (' || old_sql || '), new_rows AS MATERIALIZED (' || new_sql || '), ' ||
                'old_ordered AS (SELECT row_number() OVER (PARTITION BY i) AS ordinal, old_rows.* FROM old_rows), ' ||
                'new_ordered AS (SELECT row_number() OVER (PARTITION BY i) AS ordinal, new_rows.* FROM new_rows) ' ||
                'SELECT EXISTS ((SELECT * FROM old_ordered EXCEPT ALL SELECT * FROM new_ordered) UNION ALL ' ||
                '(SELECT * FROM new_ordered EXCEPT ALL SELECT * FROM old_ordered))'
        INTO differs USING slugs, viewers;
        IF differs THEN RAISE EXCEPTION 'ARTICLE_BATCH differs in round %', round_no; END IF;
        -- COMMENTS_BATCH: original SQL followed by the rewritten SQL from Stmt.java.
        old_sql := $old$SELECT r.i::int4,q.* FROM unnest($1::text[],$2::int8[]) WITH ORDINALITY AS r(slug,viewer,i) CROSS JOIN LATERAL (SELECT c.id,c.body,c.created_at,c.updated_at,u.username,u.bio,u.image,EXISTS(SELECT 1 FROM follows fo WHERE fo.follower_id=r.viewer AND fo.followee_id=c.author_id) FROM articles a LEFT JOIN LATERAL (SELECT id,body,created_at,updated_at,author_id FROM comments WHERE article_id=a.id ORDER BY created_at DESC,id DESC LIMIT 100) c ON true LEFT JOIN users u ON u.id=c.author_id WHERE a.slug=r.slug ORDER BY c.created_at DESC,c.id DESC) q$old$;
        new_sql := $new$WITH r AS MATERIALIZED (SELECT * FROM unnest($1::text[],$2::int8[]) WITH ORDINALITY AS r(slug,viewer,i)), m AS MATERIALIZED (SELECT r.i,r.viewer,a.id FROM r JOIN articles a ON a.slug=r.slug), ids AS (SELECT DISTINCT id FROM m), comments_deco AS MATERIALIZED (SELECT ids.id AS article_id,c.id,c.body,c.created_at,c.updated_at,c.author_id,u.username,u.bio,u.image FROM ids LEFT JOIN LATERAL (SELECT id,body,created_at,updated_at,author_id FROM comments WHERE article_id=ids.id ORDER BY created_at DESC,id DESC LIMIT 100) c ON true LEFT JOIN users u ON u.id=c.author_id) SELECT r.i::int4,c.id,c.body,c.created_at,c.updated_at,c.username,c.bio,c.image,EXISTS(SELECT 1 FROM follows fo WHERE fo.follower_id=r.viewer AND fo.followee_id=c.author_id) FROM m r JOIN comments_deco c ON c.article_id=r.id ORDER BY r.i,c.created_at DESC,c.id DESC$new$;
        EXECUTE 'WITH old_rows AS MATERIALIZED (' || old_sql || '), new_rows AS MATERIALIZED (' || new_sql || '), ' ||
                'old_ordered AS (SELECT row_number() OVER (PARTITION BY i) AS ordinal, old_rows.* FROM old_rows), ' ||
                'new_ordered AS (SELECT row_number() OVER (PARTITION BY i) AS ordinal, new_rows.* FROM new_rows) ' ||
                'SELECT EXISTS ((SELECT * FROM old_ordered EXCEPT ALL SELECT * FROM new_ordered) UNION ALL ' ||
