        IF differs THEN RAISE EXCEPTION 'ARTICLES_AUTHOR_BATCH differs in round %', round_no; END IF;
        -- ARTICLES_FAVORITED_BATCH: original SQL followed by the rewritten SQL from Stmt.java.
        old_sql := $old$SELECT r.i::int4,q.* FROM unnest($1::text[],$2::int4[],$3::int4[],$4::int8[]) WITH ORDINALITY AS r(name,lim,off,viewer,i) CROSS JOIN LATERAL (WITH page AS (SELECT id FROM (SELECT article_id AS id FROM favorites WHERE user_id=(SELECT id FROM users WHERE username=r.name) ORDER BY article_id DESC LIMIT r.lim OFFSET r.off) pg LIMIT 100), cnt AS (SELECT count(*) AS n FROM (SELECT 1 FROM favorites WHERE user_id=(SELECT id FROM users WHERE username=r.name) LIMIT 1000) s) SELECT a.id,a.slug,a.title,a.description,a.created_at,a.updated_at,ARRAY(SELECT t.name FROM article_tags at JOIN tags t ON t.id=at.tag_id WHERE at.article_id=a.id ORDER BY t.name),(SELECT count(*) FROM favorites f WHERE f.article_id=a.id),EXISTS(SELECT 1 FROM favorites f WHERE f.user_id=r.viewer AND f.article_id=a.id),u.username,u.bio,u.image,EXISTS(SELECT 1 FROM follows fo WHERE fo.follower_id=r.viewer AND fo.followee_id=a.author_id),cnt.n FROM cnt LEFT JOIN page p ON true LEFT JOIN articles a ON a.id=p.id LEFT JOIN users u ON u.id=a.author_id ORDER BY a.id DESC) q ORDER BY r.i,q.id DESC$old$;
        new_sql := $new$WITH r AS MATERIALIZED (SELECT * FROM unnest($1::text[],$2::int4[],$3::int4[],$4::int8[]) WITH ORDINALITY AS r(name,lim,off,viewer,i)), pages AS MATERIALIZED (SELECT r.i,r.viewer,p.id,p.n FROM r CROSS JOIN LATERAL (WITH page AS (SELECT id FROM (SELECT article_id AS id FROM favorites WHERE user_id=(SELECT id FROM users WHERE username=r.name) ORDER BY article_id DESC LIMIT r.lim OFFSET r.off) pg LIMIT 100), cnt AS (SELECT count(*) AS n FROM (SELECT 1 FROM favorites WHERE user_id=(SELECT id FROM users WHERE username=r.name) LIMIT 1000) s) SELECT p.id,cnt.n FROM cnt LEFT JOIN page p ON true) p), ids AS (SELECT DISTINCT id FROM pages WHERE id IS NOT NULL), deco AS MATERIALIZED (SELECT a.id,a.slug,a.title,a.description,a.created_at,a.updated_at,a.author_id,tg.tags,(SELECT count(*) FROM favorites f WHERE f.article_id=a.id) AS fav_count,u.username,u.bio,u.image FROM ids JOIN articles a ON a.id=ids.id JOIN users u ON u.id=a.author_id LEFT JOIN (SELECT at.article_id,array_agg(t.name ORDER BY t.name) AS tags FROM ids ti JOIN article_tags at ON at.article_id=ti.id JOIN tags t ON t.id=at.tag_id GROUP BY at.article_id) tg ON tg.article_id=a.id) SELECT r.i::int4,d.id,d.slug,d.title,d.description,d.created_at,d.updated_at,COALESCE(d.tags,ARRAY[]::text[]) AS array,COALESCE(d.fav_count,0::bigint) AS count,EXISTS(SELECT 1 FROM favorites f WHERE f.user_id=r.viewer AND f.article_id=d.id),d.username,d.bio,d.image,EXISTS(SELECT 1 FROM follows fo WHERE fo.follower_id=r.viewer AND fo.followee_id=d.author_id),r.n FROM pages r LEFT JOIN deco d ON d.id=r.id ORDER BY r.i,d.id DESC$new$;
        EXECUTE 'WITH old_rows AS MATERIALIZED (' || old_sql || '), new_rows AS MATERIALIZED (' || new_sql || '), ' ||
                'old_ordered AS (SELECT row_number() OVER (PARTITION BY i) AS ordinal, old_rows.* FROM old_rows), ' ||
                'new_ordered AS (SELECT row_number() OVER (PARTITION BY i) AS ordinal, new_rows.* FROM new_rows) ' ||
                'SELECT EXISTS ((SELECT * FROM old_ordered EXCEPT ALL SELECT * FROM new_ordered) UNION ALL ' ||
                '(SELECT * FROM new_ordered EXCEPT ALL SELECT * FROM old_ordered))'
        INTO differs USING user_names, limits, offsets, viewers;
        IF differs THEN RAISE EXCEPTION 'ARTICLES_FAVORITED_BATCH differs in round %', round_no; END IF;
    END LOOP;
    RAISE NOTICE 'All batched statements matched in 5 rounds';
END
$test$;
